    public static void main(String[] args) {
        try {
            int[] input = {5, 1, 4, 2, 8};
            int[] result = BubbleSorter.bubbleSort(input);
            check("returns the SAME array object", true, result == input);
            check("array sorted in place", "[1, 2, 4, 5, 8]",
                    java.util.Arrays.toString(input));
            check("sort with duplicates", "[1, 3, 3, 7, 9]",
                    java.util.Arrays.toString(BubbleSorter.bubbleSort(new int[]{3, 9, 1, 7, 3})));
