                    java.util.Arrays.toString(BubbleSorter.bubbleSort(new int[]{1, 2, 3})));
            check("reverse order", "[1, 2, 3, 4, 5]",
                    java.util.Arrays.toString(BubbleSorter.bubbleSort(new int[]{5, 4, 3, 2, 1})));
