public class BubbleSorter {

    public static int[] bubbleSort(int[] a) {
        boolean swapped = true;
        int end = a.length - 1;
        while (swapped) {
            swapped = false;
            for (int i = 0; i < end; i++) {
                if (a[i] > a[i + 1]) {
                    int temp = a[i];
                    a[i] = a[i + 1];
                    a[i + 1] = temp;
                    swapped = true;
                }
            }
            end--;
        }
        return a;
    }
}
